compose/caddyfile.stable:
# Written by the Geometer deploy bundle. Caddy reaches the inbox, the relay and the panel (the only containers on its network), and serves each shop's report pages from a read-only folder.
{
	admin off
}

shops.example.com {
	handle /c/* {
		reverse_proxy inbox:8788
	}
	# monthly report pages: only the exact file shape below is served, from each shop's reports folder (read-only); everything else under /r is a 404
	@report-area path /r /r/*
	handle @report-area {
		@report-file path_regexp ^/r/(?:glow-salon)/[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]/[A-Za-z0-9][A-Za-z0-9._-]*\.(?:html|json|txt)$
		handle @report-file {
			root * /srv
			header {
				Cache-Control "private, no-store"
				X-Content-Type-Options "nosniff"
				X-Robots-Tag "noindex"
				Referrer-Policy "no-referrer"
				Content-Security-Policy "default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"
			}
			file_server
		}
		handle {
			respond 404
		}
	}
	handle {
		reverse_proxy panel:8790
	}
}

